import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

public class CSVParser_getHeaderMap_TriageGen2Test {

    @Test
    public void testGetHeaderMap_WithValidHeaders() throws IOException {
        String csvContent = "id,name,age\n1,John,30\n2,Jane,25";
        StringReader reader = new StringReader(csvContent);
        CSVFormat format = CSVFormat.DEFAULT.withFirstRecordAsHeader();

        try (CSVParser parser = CSVParser.parse(reader, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Verify content and size
            assertEquals(3, headerMap.size());
            assertEquals(Integer.valueOf(0), headerMap.get("id"));
            assertEquals(Integer.valueOf(1), headerMap.get("name"));
            assertEquals(Integer.valueOf(2), headerMap.get("age"));

            // Verify that it returns a copy (defensive copy check)
            // The method uses new LinkedHashMap<>(this.headerMap)
            assertNotSame("The returned map should be a new instance, not the internal map reference", 
                parser.getHeaderMap(), parser.getHeaderMap());
        }
    }

    @Test
    public void testGetHeaderMap_EmptyFile() throws IOException {
        String csvContent = "";
        StringReader reader = new StringReader(csvContent);
        CSVFormat format = CSVFormat.DEFAULT.withFirstRecordAsHeader();

        try (CSVParser parser = CSVParser.parse(reader, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();
            assertTrue("Header map should be empty for an empty file", headerMap.isEmpty());
        }
    }

    @Test
    public void testGetHeaderMap_NoHeaderFormat() throws IOException {
        String csvContent = "1,John,30";
        StringReader reader = new StringReader(csvContent);
        // Using format without header configuration
        CSVFormat format = CSVFormat.DEFAULT;

        try (CSVParser parser = CSVParser.parse(reader, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();
            assertTrue("Header map should be empty when no header is defined in format", headerMap.isEmpty());
        }
    }

    @Test
    public void testGetHeaderMap_ImmutabilityOfOriginal() throws IOException {
        String csvContent = "col1\nval1";
        StringReader reader = new StringReader(csvContent);
        CSVFormat format = CSVFormat.DEFAULT.withFirstRecordAsHeader();

        try (CSVParser parser = CSVParser.parse(reader, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Modify the returned map
            headerMap.put("newCol", 99);

            // Get a new map from the parser and verify the original internal state is unchanged
            Map<String, Integer> secondCallMap = parser.getHeaderMap();
            assertEquals("The internal header map should not be affected by modifications to the returned map", 
                1, secondCallMap.size());
            assertTrue(secondCallMap.containsKey("col1"));
            assertFalse(secondCallMap.containsKey("newCol"));
        }
    }
}
